  const key = `${x | 0},${y | 0}`;
  map[key] = { expiresAtStep: (world.step | 0) + Math.max(1, turns | 0) };
}

export function isWetAt(world, x, y) {
  if (WET_TILE_TYPES.has(getTile(x | 0, y | 0))) return true;
  const map = getWetMap(world);
  if (!map) return false;
  const key = `${x | 0},${y | 0}`;
  const rec = map[key];
  if (!rec) return false;
  if ((world.step | 0) > rec.expiresAtStep) {
    delete map[key];
    return false;
  }
  return true;
}

